import{_ as o,l as s,o as e,c as n,v as t,p as l,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"KMP 串匹配","description":"","frontmatter":{"title":"KMP 串匹配","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kmp.md","filePath":"cs/kmp.md","lastUpdated":1789023840000}'),c={name:"cs/kmp.md"};function m(P,a,_,T,u,q){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="kmp-串匹配" tabindex="-1">KMP 串匹配 <a class="header-anchor" href="#kmp-串匹配" aria-label="Permalink to &quot;KMP 串匹配&quot;">​</a></h1><div class="epigraph"><p>模式在失配处已经对齐过的前缀信息，足够决定下一步滑到哪，而不把文本指针回退。</p><footer>—— 据 Knuth, Morris and Pratt, Fast Pattern Matching in Strings, 1977；CLRS 第 32 章整理</footer></div><p>上一课<a href="/cs/bipartite-match">二分图匹配</a>收束了图上的组合优化主干。串是另一类对象：文本 \\(T\\)、模式 \\(P\\)，问 \\(P\\) 是否作为连续片段出现。本课不把串当图的路径。缺口是：朴素匹配最坏 \\(\\Theta(nm)\\)，每次失配把 \\(T\\) 的指针往回退。KMP 预计算 \\(P\\) 的前缀函数，扫描 \\(T\\) 只前进。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素：每个起点 \\(s\\) 比较 \\(P\\) 与 \\(T[s..]\\)。最坏如 \\(aaa\\ldots b\\) 对 \\(aa\\ldots ab\\)。缺口不是哈希（那是期望），而是<strong>确定性线性</strong>：预处理 \\(P\\) 得 \\(\\pi\\)，使 \\(\\pi[q]\\) 为真前缀 \\(P[1..q]\\) 的最长真后缀长度且该后缀也是前缀。匹配时失配跳到 \\(\\pi[q]\\)， \\(T\\) 的下标不减。</p><p>总时间 \\(\\Theta(n+m)\\)。仍在 P，比较模型换成字符相等。</p><h3 id="前缀函数不是失败时的「往左数一格」" tabindex="-1">前缀函数不是失败时的「往左数一格」 <a class="header-anchor" href="#前缀函数不是失败时的「往左数一格」" aria-label="Permalink to &quot;前缀函数不是失败时的「往左数一格」&quot;">​</a></h3><p>\\(\\pi\\) 来自 \\(P\\) 自己的周期。错用 \\(\\pi[q]-1\\) 或固定滑 \\(1\\) 会漏匹配或退回平方。\\(\\pi\\) 的计算本身是对 \\(P\\) 的「自匹配」，同一套转移。</p><p><span class="marginnote">Knuth–Morris–Pratt 1977 把 Morris–Pratt 的思想写成线性最坏。Boyer–Moore 从右扫，本课不并行展开。后课词法用正则，那是语言而非单模式精确匹配。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先算 \\(\\pi[1..m]\\)：\\(q\\) 从 \\(0\\) 扫 \\(P\\)，失配时 \\(q\\leftarrow\\pi[q]\\)。再扫 \\(T\\)：同样转移，当 \\(q=m\\) 报告一次出现，\\(q\\leftarrow\\pi[m]\\) 找下一个。</p>',11)),(e(),l(h,null,{default:r(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%A8%A1%E5%BC%8F%20P%22%5D%20--%3E%20PI%5B%22%E5%89%8D%E7%BC%80%E5%87%BD%E6%95%B0%20%CF%80%22%5D%0A%20%20PI%20--%3E%20SCAN%5B%22%E6%89%AB%E6%96%87%E6%9C%AC%20T%EF%BC%8C%E5%A4%B1%E9%85%8D%E6%8C%89%20%CF%80%20%E8%B7%B3%22%5D%0A%20%20SCAN%20--%3E%20HIT%5B%22%E6%8A%A5%E5%91%8A%E5%87%BA%E7%8E%B0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>字符表大小不进渐近的主导项；比较是相等测试。多模式要用 Aho–Corasick，本课单模式。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>文本指针单调，故 \\(O(n)\\) 次转移；\\(\\pi\\) 的摊还同样：\\(q\\) 的增减有势函数。与<a href="/cs/amortized-analysis">摊还分析</a>同类记账，本课不重写势能定义。</p><p>哈希匹配（Rabin–Karp）期望线性、最坏平方，模型不同。本课要最坏线性。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做正则、不写近似匹配、不处理通配符。二维匹配、后缀数组是另一课序，不插入。流式只需 \\(\\pi\\) 与当前 \\(q\\)，不必存整份 \\(T\\) 的回退。</p><p>后课默认：单模式精确匹配最坏 \\(\\Theta(n+m)\\) 用 KMP。贪心作为设计法的正确性论证是下一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>前缀函数把失配变成模式内部的跳转，\\(T\\) 指针不回退。</li><li>预处理加扫描 \\(\\Theta(n+m)\\)。</li><li>单模式；正则与多模式不是本课。</li><li>出处：Knuth, Morris and Pratt, 1977；CLRS 第 32 章。</li></ul>',9))])}const A=o(c,[["render",m]]);export{f as __pageData,A as default};
